function getYoutubeIdRaw(url){
  if(!url) return null
  if(url.includes('embed/')) return url.split('embed/')[1]?.split('?')[0]?.split('&')[0]
  let id=url.split('v=')[1]; if(!id) id=url.split('youtu.be/')[1]
  if(id) id=id.split('&')[0].split('?')[0]
  return id||null
}
const getYoutubeThumb = (url) => { const id=getYoutubeIdRaw(url); return id? `https://img.youtube.com/vi/${id}/hqdefault.jpg`:null }
const getYoutubeEmbed = (url) => { const id=getYoutubeIdRaw(url); return id? `https://www.youtube.com/embed/${id}`:url }
const shuffleArray = (arr) => { const a=[...arr]; for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]] } return a }

function AdBanner({pubs, format='leaderboard'}){
  const [idx,setIdx]=useState(0)
  useEffect(()=>{ if(!pubs||pubs.length<=1) return; const id=setInterval(()=>setIdx(p=>(p+1)%pubs.length),6000); return()=>clearInterval(id) },[pubs&&pubs.length])
  if(!pubs||!pubs.length) return null
  const current=pubs[idx]
  const dims = format==='leaderboard'? {maxWidth:728,height:90} : format==='mpu'? {maxWidth:300,height:250} : {maxWidth:'100%',aspectRatio:'4/1'}
  return (
    <div style={{textAlign:'center',margin:'0 auto'}}>
      <div style={{fontSize:9,color:'rgba(255,255,255,0.4)',fontWeight:800,letterSpacing:'0.06em',marginBottom:5,textTransform:'uppercase'}}>Publicité</div>
      <a href={current.link||'#'} target="_blank" rel="noreferrer" style={{...dims,width:'100%',background:'white',borderRadius:6,overflow:'hidden',display:'block',margin:'0 auto'}}>
        <img src={current.image} style={{width:'100%',height:'100%',objectFit:'cover',display:'block'}} alt="Publicité" loading="lazy" />
      </a>
    </div>
  )
}

